// errorType identifies a typed error schema for status-code-based dispatch.
type errorType int

const (
	errorTypeNone errorType = iota
	errorTypeErrorResponse
)

type apiRequest struct {
	method       string
	pathFmt      string
	pathArgs     []any
	queryParams  any
	body         any
	successCode  int
	successCodes []int
	raw          *RawRequestOptions
	accept       string
	headers      http.Header
	// errorCodes maps HTTP status codes to a typed error schema. Status codes
	// not in this map (or decode failures) fall back to [*ResponseError].
	errorCodes map[int]errorType
}

func (c *Client) do(ctx context.Context, r apiRequest) (*http.Response, error) {
	for i, p := range r.pathArgs {
		r.pathArgs[i] = url.PathEscape(fmt.Sprint(p))
	}
	path := fmt.Sprintf(r.pathFmt, r.pathArgs...)
	if r.queryParams != nil {
		if q := encodeQuery(r.queryParams); len(q) > 0 {
			path += "?" + q.Encode()
		}
	}
	var bodyReader io.Reader
	if r.raw != nil {
		bodyReader = r.raw.Body
	} else if r.body != nil {
		b, err := json.Marshal(r.body)
		if err != nil {
			return nil, err
		}
		bodyReader = bytes.NewReader(b)
	}
	req, err := http.NewRequestWithContext(ctx, r.method, c.BaseURL+path, bodyReader)
	if err != nil {
		return nil, err
	}
	if r.body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	if r.accept != "" {
		req.Header.Set("Accept", r.accept)
	}
	for key, vals := range c.Headers {
		if len(vals) > 0 && strings.EqualFold(key, "Accept") {
			req.Header.Del(key)
		}
		for _, val := range vals {
			req.Header.Add(key, val)
		}
	}
	for k, values := range r.headers {
		req.Header.Del(k)
		for _, v := range values {
			req.Header.Add(k, v)
		}
	}
	if r.raw != nil {
		for k, values := range r.raw.Headers {
			req.Header.Del(k)
			for _, v := range values {
				req.Header.Add(k, v)
			}
		}
		if r.raw.ContentType != "" {
			req.Header.Set("Content-Type", r.raw.ContentType)
		}
		if r.raw.Accept != "" {
			req.Header.Set("Accept", r.raw.Accept)
		}
	}
	resp, err := c.HTTPClient.Do(req)
	if err != nil {
		return nil, err
	}
	success := resp.StatusCode == r.successCode
	for _, code := range r.successCodes {
		success = success || resp.StatusCode == code
	}
	if !success {
		defer resp.Body.Close()
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
		if et, ok := r.errorCodes[resp.StatusCode]; ok {
			if typedErr := decodeErrorType(et, resp.StatusCode, resp.Header, body); typedErr != nil {
				return nil, typedErr
			}
		}
		return nil, &ResponseError{StatusCode: resp.StatusCode, Body: string(body), Header: resp.Header.Clone()}
	}
	return resp, nil
}

func decodeErrorType(et errorType, statusCode int, header http.Header, body []byte) error {
	switch et {
	case errorTypeErrorResponse:
		var detail ErrorResponse
		if err := json.Unmarshal(body, &detail); err == nil {
			return &ResponseErrorResponse{StatusCode: statusCode, Header: header.Clone(), ErrorResponse: detail}
		}
	}
	return nil
}

// encodeQuery walks a Params struct emitted by oapi-codegen and renders its
// fields as url.Values using the "form" struct tag. Pointer fields that are
// nil are skipped. time.Time values are rendered as RFC 3339. Slice fields
// (including named-element slices like []Enum) are exploded into one repeated
// query parameter per element.
func encodeQuery(p any) url.Values {
	q := url.Values{}
	v := reflect.ValueOf(p)
	if v.Kind() == reflect.Ptr {
		if v.IsNil() {
			return q
		}
		v = v.Elem()
	}
	if v.Kind() != reflect.Struct {
		return q
	}
	t := v.Type()
	for i := 0; i < t.NumField(); i++ {
		tag := t.Field(i).Tag.Get("form")
		if tag == "" || tag == "-" {
			continue
		}
		name := strings.SplitN(tag, ",", 2)[0]
		if name == "" {
			continue
		}
		fv := v.Field(i)
		if fv.Kind() == reflect.Ptr {
			if fv.IsNil() {
				continue
			}
			fv = fv.Elem()
		}
		if fv.Kind() == reflect.Slice {
			for j := 0; j < fv.Len(); j++ {
				q.Add(name, fmt.Sprint(fv.Index(j).Interface()))
			}
			continue
		}
		switch x := fv.Interface().(type) {
		case time.Time:
			q.Set(name, x.Format(time.RFC3339))
		default:
			switch fv.Kind() {
			case reflect.String:
				q.Set(name, fv.String())
			case reflect.Bool:
				q.Set(name, strconv.FormatBool(fv.Bool()))
			case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
				q.Set(name, strconv.FormatInt(fv.Int(), 10))
			case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
				q.Set(name, strconv.FormatUint(fv.Uint(), 10))
			case reflect.Float32, reflect.Float64:
				q.Set(name, strconv.FormatFloat(fv.Float(), 'g', -1, 64))
			default:
				q.Set(name, fmt.Sprint(fv.Interface()))
			}
		}
	}
	return q
}

func doJSON[T any](c *Client, ctx context.Context, r apiRequest) (*T, error) {
	r.accept = "application/json"
	resp, err := c.do(ctx, r)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	if ct := resp.Header.Get("Content-Type"); !strings.HasPrefix(ct, "application/json") {
		return nil, fmt.Errorf("unexpected content type %q, expected application/json", ct)
	}
	respBody, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, err
	}
	var result T
	if err := json.Unmarshal(respBody, &result); err != nil {
		return nil, err
	}
	return &result, nil
}

func (c *Client) doNoResponse(ctx context.Context, r apiRequest) error {
	resp, err := c.do(ctx, r)
	if err != nil {
		return err
	}
	resp.Body.Close()
	return nil
}
